mapper.select:
SELECT EXISTS (
    SELECT 1 FROM team_challenges
    WHERE team_id = #{teamId} AND analysis_id = #{analysisId} AND end_date >= #{today}
)

mapper.sql:
WHERE c.team_id = #{teamId}
AND c.analysis_id = #{analysisId}
AND c.id = #{challengeId}

mapper.delete:
DELETE c FROM team_challenges c
JOIN analyses a ON a.id = c.analysis_id AND a.deleted_at IS NULL
WHERE c.team_id = #{teamId} AND c.id = #{challengeId}
